1	package netcheck
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"net/url"
8		"strings"
9		"testing"
10		"time"
11	
12		"github.com/anthnel/devdesk/internal/netproxy"
13	)
14	
15	// DEVDESK-582, acceptance criterion 5: the TCP row dials direct. When a proxy
16	// is configured for the target and that direct dial fails, "unreachable" would
17	// mislead: the conclusion says the direct path failed and that a proxy is
18	// configured for this target. Nothing else about the row changes.
19	
20	func refusedDial(context.Context, string) (time.Duration, error) {
21		return 0, errors.New("connection refused")
22	}
23	
24	func acceptedDial(context.Context, string) (time.Duration, error) {
25		return 8 * time.Millisecond, nil
26	}
27	
28	// proxiedBoth is the common case: one proxy for both schemes.
29	var proxiedBoth = perScheme(
30		decided(netproxy.DecisionProxied, "HTTPS_PROXY", "http://proxy.corp:3128"),
31		decided(netproxy.DecisionProxied, "HTTP_PROXY", "http://proxy.corp:3128"))
32	
33	func tcpRow(t *testing.T, env Env, tg Target) Check {
34		t.Helper()
35		return checkNamed(t, runWith(t, env, tg), CheckTCP)
36	}
37	
38	func TestTheDirectFailureReasonIdentifierIsStable(t *testing.T) {
39		if got := string(ReasonDirectFailedProxyConfigured); got != "direct-failed-proxy-configured" {
40			t.Errorf("identifier = %q, want %q: MCP serializes it", got, "direct-failed-proxy-configured")
41		}
42	}
43	
44	// Every way the Proxy row reads "configured" ends the same way on a failed
45	// dial, and the Proxy fact is the displayed proxy only: no variable name, no
46	// scheme tag. When the two schemes differ the https value wins, the same
47	// order the Proxy row's Summary lists them in.
48	func TestAFailedDirectDialWithAProxyConfiguredSaysSo(t *testing.T) {
49		for _, tc := range []struct {
50			name  string
51			proxy func(*url.URL) netproxy.Decision
52			port  int
53			want  string // the Proxy fact
54		}{
55			{"the same proxy for both schemes", proxiedBoth, 443, "http://proxy.corp:3128"},
56			{"another port is named as dialed", proxiedBoth, 8443, "http://proxy.corp:3128"},
57			{"a proxy for https only", perScheme(
58				decided(netproxy.DecisionProxied, "HTTPS_PROXY", "http://proxy.corp:3128"), none()),
59				443, "http://proxy.corp:3128"},
60			{"a proxy for http only", perScheme(
61				none(), decided(netproxy.DecisionProxied, "http_proxy", "http://proxy.corp:3128")),
62				443, "http://proxy.corp:3128"},
63			{"two different proxys: the https one", perScheme(
64				decided(netproxy.DecisionProxied, "HTTPS_PROXY", "http://a:3128"),
65				decided(netproxy.DecisionProxied, "HTTP_PROXY", "http://b:8080")),
66				443, "http://a:3128"},
67			{"a proxy outranks an exclusion on the other scheme", perScheme(
68				decided(netproxy.DecisionExcluded, "HTTPS_PROXY", ""),
69				decided(netproxy.DecisionProxied, "HTTP_PROXY", "http://b:8080")),
70				443, "http://b:8080"},
71			{"a proxy outranks loopback on the other scheme", perScheme(
72				decided(netproxy.DecisionProxied, "HTTPS_PROXY", "http://a:3128"),
73				decided(netproxy.DecisionLoopback, "HTTP_PROXY", "")),
74				443, "http://a:3128"},
75		} {
76			t.Run(tc.name, func(t *testing.T) {
77				tg := Target{Host: "example.com", Port: tc.port}
78				checks := runWith(t, fakeEnv{dial: refusedDial, proxy: tc.proxy}, tg)
79	
80				// The premise: the Proxy row reads "configured".
81				if p := checkNamed(t, checks, CheckProxy); p.Reason != ReasonProxyConfigured {
82					t.Fatalf("premise: proxy row reason = %q, want %q", p.Reason, ReasonProxyConfigured)
83				}
84	
85				c := checkNamed(t, checks, CheckTCP)
86				wantSummary := fmt.Sprintf(
87					"Port %d does not accept direct connections; a proxy is configured for this target", tc.port)
88				if c.Summary != wantSummary {
89					t.Errorf("summary = %q, want %q", c.Summary, wantSummary)
90				}
91				if c.Verdict != Fail {
92					t.Errorf("verdict = %v, want Fail: the direct dial did fail", c.Verdict)
93				}
94				if c.Reason != ReasonDirectFailedProxyConfigured {
95					t.Errorf("reason = %q, want %q", c.Reason, ReasonDirectFailedProxyConfigured)
96				}
97				if got := factValue(c, "Proxy"); got != tc.want {
98					t.Errorf("Proxy fact = %q, want %q", got, tc.want)
99				}
100				if got := factValue(c, "Address"); got != tg.Addr() {
101					t.Errorf("Address fact = %q, want %q: the row still describes the dial", got, tg.Addr())
102				}
103				if got := factValue(c, "Error"); got != "connection refused" {
104					t.Errorf("Error fact = %q, want the dial error kept", got)
105				}
106	
107				// The gate is unchanged: the failed direct dial still blocks what follows.
108				for _, id := range []CheckID{CheckTLSHandshake, CheckHTTP} {
109					if b := checkNamed(t, checks, id); b.Verdict != NotApplicable || b.Because != CheckTCP {
110						t.Errorf("%s = %v because %q, want N/A because %q", id, b.Verdict, b.Because, CheckTCP)
111					}
112				}
113			})
114		}
115	}
116	
117	// A dial that succeeds says what it always said: the proxy does not enter it.
118	func REDACTED(t *testing.T) {
119		c := tcpRow(t, fakeEnv{dial: acceptedDial, proxy: proxiedBoth}, target())
120	
121		if c.Verdict != OK {
122			t.Errorf("verdict = %v, want OK", c.Verdict)
123		}
124		if want := "Port 443 accepted the connection in 8 ms"; c.Summary != want {
125			t.Errorf("summary = %q, want %q", c.Summary, want)
126		}
127		if c.Reason != "" {
128			t.Errorf("reason = %q, want none on a REDACTEDing row", c.Reason)
129		}
130		if got := factValue(c, "Proxy"); got != "" {
131			t.Errorf("Proxy fact = %q, want none: the dial worked", got)
132		}
133	}
134	
135	// Without a proxy that applies, a refusal is what it was before: the conclusion
136	// only changes when a proxy is configured for this target.
137	func TestAFailedDirectDialWithoutAProxyIsUnchanged(t *testing.T) {
138		for _, tc := range []struct {
139			name  string
140			proxy func(*url.URL) netproxy.Decision
141		}{
142			{"no variable", nil},
143			{"no variable, explicitly", perScheme(none(), none())},
144			{"NO_PROXY names the target", perScheme(
145				decided(netproxy.DecisionExcluded, "HTTPS_PROXY", ""),
146				decided(netproxy.DecisionExcluded, "HTTP_PROXY", ""))},
147			{"a loopback target", perScheme(
148				decided(netproxy.DecisionLoopback, "HTTPS_PROXY", ""),
149				decided(netproxy.DecisionLoopback, "HTTP_PROXY", ""))},
150			{"an invalid variable", perScheme(decided(netproxy.DecisionInvalid, "HTTPS_PROXY", ""), none())},
151			{"both variables invalid", perScheme(
152				decided(netproxy.DecisionInvalid, "HTTPS_PROXY", ""),
153				decided(netproxy.DecisionInvalid, "HTTP_PROXY", ""))},
154		} {
155			t.Run(tc.name, func(t *testing.T) {
156				c := tcpRow(t, fakeEnv{dial: refusedDial, proxy: tc.proxy}, target())
157	
158				if c.Verdict != Fail {
159					t.Errorf("verdict = %v, want Fail", c.Verdict)
160				}
161				if want := "Port 443 does not accept connections"; c.Summary != want {
162					t.Errorf("summary = %q, want %q", c.Summary, want)
163				}
164				if c.Reason != "" {
165					t.Errorf("reason = %q, want none: no proxy applies", c.Reason)
166				}
167				if got := factValue(c, "Proxy"); got != "" {
168					t.Errorf("Proxy fact = %q, want none: no proxy applies", got)
169				}
170				if got := factValue(c, "Error"); got != "connection refused" {
171					t.Errorf("Error fact = %q, want the dial error", got)
172				}
173			})
174		}
175	}
176	
177	// The help for the new conclusion says the direct path failed and that a proxy
178	// is configured, and offers something to do that is not the generic advice
179	// about a service that is down.
180	func TestTheDirectFailureWithAProxyIsExplained(t *testing.T) {
181		c := tcpRow(t, fakeEnv{dial: refusedDial, proxy: proxiedBoth}, target())
182		e := Explain(c)
183	
184		wantMeans := "The direct path to this port is closed, and that is all this run tests. A proxy is " +
185			"configured for this target: behind a mandatory proxy a closed direct path is expected, " +
186			"and it says nothing about whether the target is up."
187		if e.Means != wantMeans {
188			t.Errorf("means = %q, want %q", e.Means, wantMeans)
189		}
190		for _, word := range []string{"direct path", "proxy"} {
191			if !strings.Contains(e.Means, word) {
192				t.Errorf("means %q does not say %q", e.Means, word)
193			}
194		}
195	
196		wantDo := "If this target is meant to be reached through the proxy, check it from a client that " +
197			"uses it, such as an HTTPS monitor in the Status view. If it is meant to be reached " +
198			"directly, add it to NO_PROXY and look for what drops the connection."
199		if e.Do != wantDo {
200			t.Errorf("do = %q, want %q", e.Do, wantDo)
201		}
202	
203		generic := Explain(tcpRow(t, fakeEnv{dial: refusedDial}, target()))
204		if strings.TrimSpace(e.Do) == "" || e.Do == generic.Do {
205			t.Errorf("do = %q: it must be non-empty and differ from the generic TCP Fail advice", e.Do)
206		}
207		if e.Means == generic.Means {
208			t.Error("the explanation is the generic TCP Fail one: it does not mention the proxy")
209		}
210		if e.Observed != c.Summary {
211			t.Errorf("observed = %q, want the summary %q", e.Observed, c.Summary)
212		}
213	}
214	
215	// The guidance row is a row of the table, not a branch in code: it is reached
216	// by a battery scenario (TestNoGuidanceRowIsUnreachable fails otherwise), says
217	// something about the failed state, and leaves the generic row for the other
218	// failures.
219	func TestTheDirectFailureGuidanceRowIsInTheTableAndReachable(t *testing.T) {
220		var rows int
221		for _, g := range explanations {
222			if g.check == CheckTCP && g.verdict == Fail && g.reason == ReasonDirectFailedProxyConfigured {
223				rows++
224				if strings.TrimSpace(g.do) == "" {
225					t.Error("the guidance row has nothing to do about the failure")
226				}
227			}
228		}
229		if rows != 1 {
230			t.Fatalf("explanations has %d rows for tcp/fail/%s, want 1", rows, ReasonDirectFailedProxyConfigured)
231		}
232	
233		var reached bool
234		for _, c := range produced(t) {
235			if c.ID == CheckTCP && c.Verdict == Fail && c.Reason == ReasonDirectFailedProxyConfigured {
236				reached = true
237			}
238		}
239		if !reached {
240			t.Error("no scenario of the battery produces the TCP direct-failed-proxy-configured row")
241		}
242	
243		// The generic row still serves the failures with no proxy.
244		generic := Explain(Check{ID: CheckTCP, Verdict: Fail, Summary: "x"})
245		if strings.Contains(generic.Means, "proxy") {
246			t.Errorf("the generic TCP Fail explanation mentions a proxy: %q", generic.Means)
247		}
248	}
249	
250	// The proxy is shown redacted by netproxy, and the TCP row must not put a
251	// credential back: no summary, fact or explanation carries "@" or a secret.
252	func TestTheDirectFailureRowCarriesNoCredential(t *testing.T) {
253		// What netproxy hands over for REDACTED is scheme://host:port.
254		redacted := perScheme(
255			decided(netproxy.DecisionProxied, "HTTPS_PROXY", "http://proxy.corp:3128"),
256			decided(netproxy.DecisionProxied, "HTTP_PROXY", "http://proxy.corp:3128"))
257	
258		c := tcpRow(t, fakeEnv{dial: refusedDial, proxy: redacted}, target())
259		if c.Reason != ReasonDirectFailedProxyConfigured {
260			t.Fatalf("premise: reason = %q, want %q", c.Reason, ReasonDirectFailedProxyConfigured)
261		}
262		e := Explain(c)
263	
264		texts := []string{c.Summary, e.Observed, e.Means, e.Do}
265		for _, f := range c.Facts {
266			texts = append(texts, f.Key, f.Value)
267		}
268		for _, s := range texts {
269			for _, bad := range []string{"@", secretUser, secretPass} {
270				if strings.Contains(s, bad) {
271					t.Errorf("%q contains %q", s, bad)
272				}
273			}
274		}
275	}
276	
277	// An invalid variable for one scheme and a valid proxy for the other: the Proxy
278	// row merges to Invalid, but a proxy is configured all the same, so a failed
279	// direct dial still says so. The TCP stage reads the row's field, not its text.
280	func TestAFailedDirectDialWithOneInvalidAndOneProxiedSchemeNamesTheProxy(t *testing.T) {
281		proxy := perScheme(
282			decided(netproxy.DecisionInvalid, "HTTPS_PROXY", ""),
283			decided(netproxy.DecisionProxied, "HTTP_PROXY", "http://proxy.corp:3128"))
284		checks := runWith(t, fakeEnv{dial: refusedDial, proxy: proxy}, target())
285	
286		if p := checkNamed(t, checks, CheckProxy); p.Reason != ReasonProxyInvalid {
287			t.Fatalf("premise: proxy row reason = %q, want %q", p.Reason, ReasonProxyInvalid)
288		}
289		c := checkNamed(t, checks, CheckTCP)
290		if c.Reason != ReasonDirectFailedProxyConfigured {
291			t.Errorf("reason = %q, want %q", c.Reason, ReasonDirectFailedProxyConfigured)
292		}
293		if want := "Port 443 does not accept direct connections; a proxy is configured for this target"; c.Summary != want {
294			t.Errorf("summary = %q, want %q", c.Summary, want)
295		}
296		if got := factValue(c, "Proxy"); got != "http://proxy.corp:3128" {
297			t.Errorf("Proxy fact = %q, want the proxied scheme's proxy", got)
298		}
299	}
