1	package netcheck
2	
3	import (
4		"context"
5		"crypto/ecdsa"
6		"crypto/elliptic"
7		"crypto/rand"
8		"crypto/tls"
9		"crypto/x509"
10		"crypto/x509/pkix"
11		"errors"
12		"math/big"
13		"net"
14		"net/url"
15		"testing"
16		"time"
17	
18		"github.com/anthnel/devdesk/internal/netproxy"
19	)
20	
21	// testNow is the clock every test runs against, so an expiry assertion does not
22	// depend on the day the suite runs.
23	var testNow = time.Date(2026, 6, 1, 12, 0, 0, 0, time.UTC)
24	
25	// fakeEnv is an Env whose every primitive can be overridden one at a time.
26	// Anything left nil answers plausibly, so a test states only the condition it
27	// is about.
28	type fakeEnv struct {
29		resolve   func(ctx context.Context, host, resolver string) ([]net.IP, error)
30		reverse   func(ctx context.Context, ip, resolver string) ([]string, error)
31		ping      func(ctx context.Context, host string, count int) (PingStats, error)
32		dial      func(ctx context.Context, addr string) (time.Duration, error)
33		handshake func(ctx context.Context, addr, serverName string) (*tls.ConnectionState, error)
34		head      func(ctx context.Context, url string) (HTTPResult, error)
35		route     func(ctx context.Context, ip net.IP) (RouteHop, error)
36		proxy     func(u *url.URL) netproxy.Decision
37		roots     *x509.CertPool
38		now       time.Time
39	}
40	
41	func (f fakeEnv) Resolve(ctx context.Context, host, resolver string) ([]net.IP, error) {
42		if f.resolve != nil {
43			return f.resolve(ctx, host, resolver)
44		}
45		return []net.IP{net.ParseIP("93.184.216.34")}, nil
46	}
47	
48	func (f fakeEnv) ReverseLookup(ctx context.Context, ip, resolver string) ([]string, error) {
49		if f.reverse != nil {
50			return f.reverse(ctx, ip, resolver)
51		}
52		return nil, errors.New("no such host")
53	}
54	
55	func (f fakeEnv) Ping(ctx context.Context, host string, count int) (PingStats, error) {
56		if f.ping != nil {
57			return f.ping(ctx, host, count)
58		}
59		return PingStats{Sent: count, Received: count, AvgRTT: 12 * time.Millisecond}, nil
60	}
61	
62	func (f fakeEnv) Route(ctx context.Context, ip net.IP) (RouteHop, error) {
63		if f.route != nil {
64			return f.route(ctx, ip)
65		}
66		return RouteHop{
67			Interface: "eth0",
68			Source:    net.ParseIP("192.168.1.21"),
69			Gateway:   net.ParseIP("192.168.1.1"),
70		}, nil
71	}
72	
73	// ProxyFor answers "no proxy" unless a test overrides it, so no test depends on
74	// the proxy variables of the machine it runs on.
75	func (f fakeEnv) ProxyFor(u *url.URL) netproxy.Decision {
76		if f.proxy != nil {
77			return f.proxy(u)
78		}
79		return netproxy.Decision{Kind: netproxy.DecisionNone}
80	}
81	
82	func (f fakeEnv) DialTCP(ctx context.Context, addr string) (time.Duration, error) {
83		if f.dial != nil {
84			return f.dial(ctx, addr)
85		}
86		return 8 * time.Millisecond, nil
87	}
88	
89	func (f fakeEnv) Handshake(ctx context.Context, addr, serverName string) (*tls.ConnectionState, error) {
90		if f.handshake != nil {
91			return f.handshake(ctx, addr, serverName)
92		}
93		return nil, tls.RecordHeaderError{Msg: "first record does not look like a TLS handshake"}
94	}
95	
96	func (f fakeEnv) Head(ctx context.Context, url string) (HTTPResult, error) {
97		if f.head != nil {
98			return f.head(ctx, url)
99		}
100		return HTTPResult{Status: 200, Server: "nginx"}, nil
101	}
102	
103	func (f fakeEnv) TrustRoots() *x509.CertPool { return f.roots }
104	
105	func (f fakeEnv) Now() time.Time {
106		if f.now.IsZero() {
107			return testNow
108		}
109		return f.now
110	}
111	
112	// --- certificate minting -----------------------------------------------------
113	
114	var serial int64
115	
116	func nextSerial() *big.Int {
117		serial++
118		return big.NewInt(serial)
119	}
120	
121	// mint issues a certificate from tmpl. A nil parent means self-signed.
122	func mint(t *testing.T, tmpl, parent *x509.Certificate, parentKey *ecdsa.PrivateKey) (*x509.Certificate, *ecdsa.PrivateKey) {
123		t.Helper()
124	
125		key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
126		if err != nil {
127			t.Fatalf("generate key: %v", err)
128		}
129		signee, signer := parent, parentKey
130		if parent == nil {
131			signee, signer = tmpl, key
132		}
133	
134		der, err := x509.CreateCertificate(rand.Reader, tmpl, signee, &key.PublicKey, signer)
135		if err != nil {
136			t.Fatalf("create certificate: %v", err)
137		}
138		cert, err := x509.ParseCertificate(der)
139		if err != nil {
140			t.Fatalf("parse certificate: %v", err)
141		}
142		return cert, key
143	}
144	
145	func caTemplate(cn string) *x509.Certificate {
146		return &x509.Certificate{
147			SerialNumber:          nextSerial(),
148			Subject:               pkix.Name{CommonName: cn},
149			NotBefore:             testNow.Add(-365 * 24 * time.Hour),
150			NotAfter:              testNow.Add(365 * 24 * time.Hour),
151			KeyUsage:              x509.KeyUsageCertSign | x509.KeyUsageDigitalSignature,
152			BasicConstraintsValid: true,
153			IsCA:                  true,
154		}
155	}
156	
157	// chainOpts describes the certificate situation a test wants to reproduce.
158	type chainOpts struct {
159		dnsNames  []string
160		ips       []net.IP
161		notBefore time.Time
162		notAfter  time.Time
163		// withIntermediate mints root -> intermediate -> leaf and has the server
164		// present both leaf and intermediate.
165		withIntermediate bool
166		// omitIntermediate presents the leaf alone even though it was signed by an
167		// intermediate — the "server forgot its chain" case.
168		omitIntermediate bool
169		// selfSigned mints a leaf that signed itself.
170		selfSigned bool
171		version    uint16
172	}
173	
174	// buildChain returns a connection state as a server would present it, plus the
175	// pool a client would have to trust for it to verify.
176	func buildChain(t *testing.T, o chainOpts) (*tls.ConnectionState, *x509.CertPool) {
177		t.Helper()
178	
179		notAfter := o.notAfter
180		if notAfter.IsZero() {
181			notAfter = testNow.Add(90 * 24 * time.Hour)
182		}
183		version := o.version
184		if version == 0 {
185			version = tls.VersionTLS13
186		}
187		notBefore := o.notBefore
188		if notBefore.IsZero() {
189			notBefore = testNow.Add(-24 * time.Hour)
190			// An expired certificate still has to have been valid once, or x509
191			// rejects the template rather than the expiry.
192			if !notAfter.After(notBefore) {
193				notBefore = notAfter.Add(-365 * 24 * time.Hour)
194			}
195		}
196		leafTmpl := &x509.Certificate{
197			SerialNumber:          nextSerial(),
198			Subject:               pkix.Name{CommonName: "leaf"},
199			DNSNames:              o.dnsNames,
200			IPAddresses:           o.ips,
201			NotBefore:             notBefore,
202			NotAfter:              notAfter,
203			KeyUsage:              x509.KeyUsageDigitalSignature,
204			ExtKeyUsage:           []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
205			BasicConstraintsValid: true,
206		}
207	
208		if o.selfSigned {
209			leaf, _ := mint(t, leafTmpl, nil, nil)
210			return &tls.ConnectionState{Version: version, PeerCertificates: []*x509.Certificate{leaf}}, x509.NewCertPool()
211		}
212	
213		root, rootKey := mint(t, caTemplate("test root"), nil, nil)
214		pool := x509.NewCertPool()
215		pool.AddCert(root)
216	
217		signerCert, signerKey := root, rootKey
218		var intermediate *x509.Certificate
219		if o.withIntermediate || o.omitIntermediate {
220			intermediate, signerKey = mint(t, caTemplate("test intermediate"), root, rootKey)
221			signerCert = intermediate
222		}
223	
224		leaf, _ := mint(t, leafTmpl, signerCert, signerKey)
225	
226		presented := []*x509.Certificate{leaf}
227		if o.withIntermediate && !o.omitIntermediate {
228			presented = append(presented, intermediate)
229		}
230		return &tls.ConnectionState{Version: version, PeerCertificates: presented}, pool
231	}
232	
233	// --- assertions --------------------------------------------------------------
234	
235	func verdictOf(t *testing.T, checks []Check, id CheckID) Verdict {
236		t.Helper()
237		for _, c := range checks {
238			if c.ID == id {
239				return c.Verdict
240			}
241		}
242		t.Fatalf("check %q was not produced; got %v", id, idsOf(checks))
243		return Unknown
244	}
245	
246	func checkNamed(t *testing.T, checks []Check, id CheckID) Check {
247		t.Helper()
248		for _, c := range checks {
249			if c.ID == id {
250				return c
251			}
252		}
253		t.Fatalf("check %q was not produced; got %v", id, idsOf(checks))
254		return Check{}
255	}
256	
257	func idsOf(checks []Check) []CheckID {
258		out := make([]CheckID, 0, len(checks))
259		for _, c := range checks {
260			out = append(out, c.ID)
261		}
262		return out
263	}
