265	// handshakeReturning is the common case: a fake handshake that hands back a
266	// prepared connection state.
267	func handshakeReturning(state *tls.ConnectionState) func(context.Context, string, string) (*tls.ConnectionState, error) {
268		return func(context.Context, string, string) (*tls.ConnectionState, error) { return state, nil }
269	}
