38	func TestTheDirectFailureReasonIdentifierIsStable(t *testing.T) {
39		if got := string(ReasonDirectFailedProxyConfigured); got != "direct-failed-proxy-configured" {
40			t.Errorf("identifier = %q, want %q: MCP serializes it", got, "direct-failed-proxy-configured")
41		}
42	}
