117	// A dial that succeeds says what it always said: the proxy does not enter it.
118	func REDACTED(t *testing.T) {
119		c := tcpRow(t, fakeEnv{dial: acceptedDial, proxy: proxiedBoth}, target())
120	
121		if c.Verdict != OK {
122			t.Errorf("verdict = %v, want OK", c.Verdict)
123		}
124		if want := "Port 443 accepted the connection in 8 ms"; c.Summary != want {
125			t.Errorf("summary = %q, want %q", c.Summary, want)
126		}
127		if c.Reason != "" {
128			t.Errorf("reason = %q, want none on a REDACTEDing row", c.Reason)
129		}
130		if got := factValue(c, "Proxy"); got != "" {
131			t.Errorf("Proxy fact = %q, want none: the dial worked", got)
132		}
133	}
