177	// The help for the new conclusion says the direct path failed and that a proxy
178	// is configured, and offers something to do that is not the generic advice
179	// about a service that is down.
180	func TestTheDirectFailureWithAProxyIsExplained(t *testing.T) {
181		c := tcpRow(t, fakeEnv{dial: refusedDial, proxy: proxiedBoth}, target())
182		e := Explain(c)
183	
184		wantMeans := "The direct path to this port is closed, and that is all this run tests. A proxy is " +
185			"configured for this target: behind a mandatory proxy a closed direct path is expected, " +
186			"and it says nothing about whether the target is up."
187		if e.Means != wantMeans {
188			t.Errorf("means = %q, want %q", e.Means, wantMeans)
189		}
190		for _, word := range []string{"direct path", "proxy"} {
191			if !strings.Contains(e.Means, word) {
192				t.Errorf("means %q does not say %q", e.Means, word)
193			}
194		}
195	
196		wantDo := "If this target is meant to be reached through the proxy, check it from a client that " +
197			"uses it, such as an HTTPS monitor in the Status view. If it is meant to be reached " +
198			"directly, add it to NO_PROXY and look for what drops the connection."
199		if e.Do != wantDo {
200			t.Errorf("do = %q, want %q", e.Do, wantDo)
201		}
202	
203		generic := Explain(tcpRow(t, fakeEnv{dial: refusedDial}, target()))
204		if strings.TrimSpace(e.Do) == "" || e.Do == generic.Do {
205			t.Errorf("do = %q: it must be non-empty and differ from the generic TCP Fail advice", e.Do)
206		}
207		if e.Means == generic.Means {
208			t.Error("the explanation is the generic TCP Fail one: it does not mention the proxy")
209		}
210		if e.Observed != c.Summary {
211			t.Errorf("observed = %q, want the summary %q", e.Observed, c.Summary)
212		}
213	}
