215	// The guidance row is a row of the table, not a branch in code: it is reached
216	// by a battery scenario (TestNoGuidanceRowIsUnreachable fails otherwise), says
217	// something about the failed state, and leaves the generic row for the other
218	// failures.
219	func TestTheDirectFailureGuidanceRowIsInTheTableAndReachable(t *testing.T) {
220		var rows int
221		for _, g := range explanations {
222			if g.check == CheckTCP && g.verdict == Fail && g.reason == ReasonDirectFailedProxyConfigured {
223				rows++
224				if strings.TrimSpace(g.do) == "" {
225					t.Error("the guidance row has nothing to do about the failure")
226				}
227			}
228		}
229		if rows != 1 {
230			t.Fatalf("explanations has %d rows for tcp/fail/%s, want 1", rows, ReasonDirectFailedProxyConfigured)
231		}
232	
233		var reached bool
234		for _, c := range produced(t) {
235			if c.ID == CheckTCP && c.Verdict == Fail && c.Reason == ReasonDirectFailedProxyConfigured {
236				reached = true
237			}
238		}
239		if !reached {
240			t.Error("no scenario of the battery produces the TCP direct-failed-proxy-configured row")
241		}
242	
243		// The generic row still serves the failures with no proxy.
244		generic := Explain(Check{ID: CheckTCP, Verdict: Fail, Summary: "x"})
245		if strings.Contains(generic.Means, "proxy") {
246			t.Errorf("the generic TCP Fail explanation mentions a proxy: %q", generic.Means)
247		}
248	}
