39	// TestEveryStageProducesWhatItDeclares keeps the `produces` list honest. The
40	// skip path names checks from that list alone, so a stage that grew a check
41	// without declaring it would go missing precisely when something upstream
42	// failed — the moment the list matters most.
43	func TestEveryStageProducesWhatItDeclares(t *testing.T) {
44		// Two shapes per stage, because a stage's check set must not depend on how
45		// its probe went: the TLS stage returns five checks whether the handshake
46		// succeeded or not, and that is the property being pinned.
47		state, roots := buildChain(t, chainOpts{dnsNames: []string{"example.com"}, withIntermediate: true})
48	
49		for _, s := range stages() {
50			for _, env := range []Env{
51				fakeEnv{roots: roots, handshake: handshakeReturning(state)},
52				fakeEnv{
53					resolve: func(context.Context, string, string) ([]net.IP, error) { return nil, errors.New("nxdomain") },
54					ping:    func(context.Context, string, int) (PingStats, error) { return PingStats{}, errors.New("no socket") },
55					dial:    func(context.Context, string) (time.Duration, error) { return 0, errors.New("refused") },
56					head:    func(context.Context, string) (HTTPResult, error) { return HTTPResult{}, errors.New("eof") },
57				},
58			} {
59				var prior Results
60				got := idsOf(s.run(context.Background(), target(), env, DefaultSettings(), &prior))
61				if len(got) != len(s.produces) {
62					t.Fatalf("stage %q produced %v, declares %v", s.id, got, s.produces)
63				}
64				declared := make(map[CheckID]bool, len(s.produces))
65				for _, id := range s.produces {
66					declared[id] = true
67				}
68				for _, id := range got {
69					if !declared[id] {
70						t.Fatalf("stage %q produced undeclared check %q", s.id, id)
71					}
72				}
73			}
74		}
75	}
