		if c.Reason != "" {
			t.Errorf("Reason = %q, want empty — this is not the server-misbehaving case", c.Reason)
		}
		if got := factValue(c, "Temporary"); got != "" {
			t.Errorf("Temporary fact = %q, want none outside the server-misbehaving case", got)
